mapper.update:

MERGE INTO CRM_SMS_MGT A
USING DUAL
ON (
    A.SMS_CODE_GRP = #{sms_code_grp}
    AND
    A.SMS_CODE = #{sms_code}
)
WHEN MATCHED THEN
    UPDATE SET
        A.USE_YN = #{use_yn} 
        ,A.UPD_ID = #{reg_id}
        ,A.UPD_DATE = SYSDATE
WHEN NOT MATCHED THEN
    INSERT(
		SMS_CODE_GRP		,SMS_CODE		    ,USE_YN		    ,TITLE
    	,CNTN						,REG_ID			    ,REG_DATE		,GUBUN	   
    )VALUES(
		#{sms_code_grp}		,#{sms_code}		,#{use_yn}		,#{title}
    	,#{cntn}					,#{reg_id}				,SYSDATE	  		,#{gubun}
    )


MERGE INTO CRM_SMS_MGT A
USING DUAL
ON (
    A.SMS_CODE_GRP = #{sms_code_grp}
    AND
    A.SMS_CODE = #{sms_code}
)
WHEN MATCHED THEN
    UPDATE SET
        A.USE_YN = #{use_yn} 
        ,A.TITLE = #{title}
        ,A.CNTN = #{cntn}
        ,A.UPD_ID = #{reg_id}
        ,A.UPD_DATE = SYSDATE
WHEN NOT MATCHED THEN
    INSERT(
		SMS_CODE_GRP		,SMS_CODE		    ,USE_YN		    ,TITLE
    	,CNTN						,REG_ID			    ,REG_DATE		,GUBUN	   
    )VALUES(
		#{sms_code_grp}		,#{sms_code}		,#{use_yn}		,#{title}
    	,#{cntn}					,#{reg_id}				,SYSDATE	  		,#{gubun}
    )
